style.css:
@-moz-document domain("bandlab.com") {
/* ======================================
   BANDLAB - ROSE QUARTZ THEME
====================================== */

:root {
    --bg-main: #211a20;
    --bg-panel: #30242e;
    --bg-header: #392a35;
    --bg-control: #493342;

    --pink: #d994b4;
    --pink-light: #edbfd3;
    --pink-dark: #a96587;

    --text-main: #f8eaf1;
    --text-muted: #c6aab9;

    --border: #59404f;
}

/* MAIN BACKGROUND */
body,
main,
div[class*="app"],
div[class*="studio"] {
    background-color: var(--bg-main) !important;
    color: var(--text-main) !important;
}

/* HEADER */
header,
nav,
div[class*="header"],
div[class*="nav"] {
    background-color: var(--bg-header) !important;
    color: var(--text-main) !important;
    border-color: var(--border) !important;
}

/* SIDEBAR & TRACK CONTROLS */
div[class*="sidebar"],
div[class*="track-header"],
div[class*="track-control"] {
    background-color: var(--bg-panel) !important;
    color: var(--text-main) !important;
    border-color: var(--border) !important;
}

/* TRACK LANES */
div[class*="track-lane"],
div[class*="timeline"],
div[class*="arrangement"] {
    background-color: #261e25 !important;
    border-color: #493541 !important;
}

/* BUTTONS */
button {
    background-color: var(--bg-control) !important;
    color: var(--text-main) !important;
    border: 1px solid var(--border) !important;
    border-radius: 5px !important;
}

button:hover {
    background-color: #65465a !important;
    border-color: var(--pink) !important;
}

/* ACTIVE BUTTONS */
button[class*="active"],
button[class*="primary"],
.is-active {
    background-color: var(--pink-dark) !important;
    color: #ffffff !important;
    border-color: var(--pink) !important;
}

/* PLAYHEAD */
div[class*="playhead"],
div[class*="scrubber"] {
    background-color: #f28db9 !important;
}

/* BOTTOM PANELS */
div[class*="bottom-panel"],
div[class*="piano-roll"],
div[class*="fx-rack"] {
    background-color: var(--bg-panel) !important;
    color: var(--text-main) !important;
    border-color: var(--border) !important;
}

/* MIXER */
div[class*="mixer"],
div[class*="channel"] {
    background-color: #30242e !important;
    border-color: var(--border) !important;
}

/* INPUTS */
input,
textarea {
    background-color: #261e25 !important;
    color: var(--text-main) !important;
    border: 1px solid var(--border) !important;
    border-radius: 4px !important;
}

input:focus,
textarea:focus {
    border-color: var(--pink) !important;
    outline: none !important;
}

/* TEXT */
h1, h2, h3, label {
    color: var(--text-main) !important;
}

/* DIVIDERS */
hr,
[class*="divider"] {
    border-color: var(--border) !important;
}

/* SCROLLBARS */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: #211a20 !important;
}

::-webkit-scrollbar-thumb {
    background: #79566b !important;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--pink-dark) !important;
}

/* TEXT SELECTION */
::selection {
    background: #a96587 !important;
    color: #ffffff !important;
}
}
